class JsonView extends MappingJackson2JsonView {

  @BeanProperty
  var jsonpCallbackParam: String = "callback"

  override def renderMergedOutputModel(model: util.Map[String, _], request: HttpServletRequest, response: HttpServletResponse): Unit = {
    val callback = request.getParameter(jsonpCallbackParam)
    if (callback != null && callback.nonEmpty) {
      val jsonp = new JSONPObject(callback, JsonUtils.toJson(model.get(getModelKey())))
      response.getWriter.write(jsonp.toString)
    } else {
      super.renderMergedOutputModel(model, request, response)
    }
  }

  private def getModelKey(): String = {
    val modelKeys = getModelKeys()
    if (modelKeys != null && !modelKeys.isEmpty) {
      modelKeys.iterator().next()
    } else {
      null
    }
  }
}

