* A JSON view that handles JSONP requests.
 *
 * @author Oleg Zhurakousky
 * @author Dmitriy Yefremov
 */
class JsonView extends MappingJackson2JsonView {

  /**
   * JSONP query parameter name.
   */
  @BeanProperty
  var jsonpParameterName: String = "callback"

  override def renderMergedOutputModel(model: util.Map[_, _], request: HttpServletRequest, response: HttpServletResponse): Unit = {
    // Check for JSONP callback parameter
    val callbackParam = request.getParameter(jsonpParameterName)
    val value = filterModel(model)

    if (callbackParam != null && callbackParam.nonEmpty) {
      // JSONP response
      response.setContentType("application/javascript")
      val jsonpObject = new JSONPObject(callbackParam, value)
      val writer = response.getWriter
      writer.write(JsonUtils.serialize(jsonpObject))
    } else {
      // Regular JSON response
      super.renderMergedOutputModel(model.asInstanceOf[util.Map[String, _]], request, response)
    }
  }

}

