  private def connected(connector: ActorRef): Receive = {
    case QueryCommand(view, key, options) =>
      val request = buildRequest(view, key, options)
      val pipeline = sendReceive(connector) ~> unmarshal[ViewResponse]
      val originalSender = sender()
      pipeline(request).onComplete {
        case Success(response) => originalSender ! response
        case Failure(ex) => originalSender ! Status.Failure(ex)
      }
    case _: Http.ConnectionClosed =>
      context.become(receive)
      self ! PoisonPill
  }

  private def buildRequest(view: View, key: Option[String], options: Map[String, String]): HttpRequest = {
    val path = s"/$bucket/_design/${view.designDoc.name}/_view/${view.name}"
    val uri = Uri(path).withQuery(Uri.Query(options ++ key.map("key" -> _)))
    val authHeader = if (user.nonEmpty && passwd.nonEmpty) {
      val credentials = java.util.Base64.getEncoder.encodeToString(s"$user:$passwd".getBytes("UTF-8"))
      HttpHeaders.Authorization(HttpCredentials.createBasicAuthCredentials(user

}

  private def connected(connector: ActorRef): Receive = {
    case QueryCommand(view, key, options, requester) =>
      implicit val timeout = Timeout(30, TimeUnit.SECONDS)
      import context.dispatcher

      val pipeline = sendReceive(connector)
      val uri = view.uri(couchApiBase, bucket, key, options)
      val request = Get(uri)
      val authenticatedRequest = if (user.nonEmpty && passwd.nonEmpty) {
        request ~> addCredentials(BasicHttpCredentials(user, passwd))
      } else request

      val response: Future[HttpResponse] = pipeline(authenticatedRequest)

      response.onComplete {
        case Success(resp) =>
          requester ! resp
        case Failure(ex) =>
          requester ! Status.Failure(ex)
      }

    case other: Command =>
      log.warning(s"Received unexpected command in connected state: $other")
  }

  override def postStop(): Unit = {
    log.info("ViewActor stopped")
  }
}

