    case ApiStringValue(t)     ⇒ JsString(t)
    case ApiDoubleValue(d)     ⇒ JsNumber(d)
    case ApiInt32Value(i)      ⇒ JsNumber(i)
    case ApiInt64Value(l)      ⇒ JsNumber(l)
    case ApiArrayValue(values) ⇒ JsArray(values map toJs)
  }

}

