override def getEventsForObjects(
      mid: MuseumId,
      objectIds: Seq[ObjectUUID]
  ): FutureMusitResult[Seq[ConservationEvent]] = {
    val actions = {
      val baseQuery = allEvents
        .filter(e => e.museumId === mid && (e.eventTypeId === MaterialDetermination.EventTypeId))
        .filter(ce => ce.affectedThingUuid.inSet(objectIds))
        .joinLeft(eaEventMaterialTable)
        .on(_.id === _.eventId)
        .result

      baseQuery.map { rows =>
        rows
          .groupBy { case (ceRow, _) => ceRow }
          .map { case (ceRow, matRows) =>
            val materialInfos = matRows.flatMap { case (_, matRowOpt) =>
              matRowOpt.map { matRow =>
                MaterialInfo(matRow.materialId, matRow.materialExtra, matRow.sorting)
              }
            }
            val baseEvent = fromRow(ceRow)
            baseEvent.copy(
              materialInfo = if (materialInfos.nonEmpty) Some(materialInfos) else None
            )
          }
          .to

