      mid: MuseumId,
      event: ConservationEvent,
      eventId: EventId,
      objectIds: Seq[ObjectUUID]
  ): FutureMusitResult[Option[ConservationEvent]] = {
    // MaterialDetermination doesn't support objects, so we just update the event itself
    update(mid, eventId, event)
