  override def getEventWithObjectsAction(
      mid: MuseumId,
      eventId: EventId
  ): DBIO[
    Option[(ConservationEvent, Option[Boolean], Option[Boolean], Seq[ObjectUUID])]
  ] = {
    // MaterialDetermination doesn't have objects, so we return empty sequence
    for {
      maybeE <- getEventAction(mid, eventId)
      enriched <- maybeE match {
                    case Some(e) =>
                      enrichWithSpecialAttributesAction(eventId, e).map(Some(_))
